from contextlib import contextmanager

@contextmanager
def open_file(path, mode="r"):
    f = open(path, mode)
    try:
        yield f  # значение для `as`
    finally:
        f.close()

with open_file("data.txt") as f:
    content = f.read()

@contextmanager
def transaction(db):
    try:
        yield db
        db.commit()
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()

with transaction(db) as tx:
    tx.execute("INSERT ...")

